use super::*;

// These expected locks were recorded from the repository-selected Cargo.
// Workspaces are created for each test; no source checkout is a test input.
pub(super) fn workspace(name: &str) -> (LocalFixture, Catalog) {
    let temporary = LocalFixture::new();
    let (files, records) = data(name);
    let write = |directory: &Path| {
        for (path, text) in files {
            let path = directory.join(path);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, text).unwrap();
        }
        for text in records {
            let record: serde_json::Value = serde_json::from_str(text).unwrap();
            let package = format!(
                "{}-{}",
                record["name"].as_str().unwrap(),
                record["vers"].as_str().unwrap()
            );
            fs::write(
                directory
                    .join("registry")
                    .join(package)
                    .join(".cargo-checksum.json"),
                serde_json::to_vec(&serde_json::json!({"files":{}, "package":record["cksum"]}))
                    .unwrap(),
            )
            .unwrap();
        }
    };
    write(&temporary.0);
    // The host gate checks these same expectations against Cargo. It asks
    // this test to export its inputs, then invokes Cargo outside the test.
    #[cfg(unix)]
    if let Some(export) = std::env::var_os("LORRY_RESOLUTION_ORACLE_EXPORT") {
        let directory = Path::new(&export).join(name);
        fs::create_dir(&directory).unwrap();
        write(&directory);
        fs::copy(
            directory.join("root/Cargo.lock"),
            directory.join("expected.lock"),
        )
        .unwrap();
    }
    let mut catalog = Catalog::default();
    for text in records {
        catalog
            .insert(
                Record::parse(Path::new("index-record"), format!("{text}\n").as_bytes()).unwrap(),
            )
            .unwrap();
    }
    (temporary, catalog)
}

